const shops={university:{name:'University',google:'https://share.google/LBehLvpyAYSQPITWq'},scottsdale:{name:'Scottsdale',google:'https://maps.app.goo.gl/cZYWJqu7rD9Xbt7UA'}};
extras.location=extras.location||'scottsdale';
extras.conversations=extras.conversations||[{id:'john-alex',client:'John B.',barber:'alex',kind:'barber',messages:[{role:'Barber Pro',name:'Lara',body:'Hi John. Let me know what you have in mind for your next visit.'}]},{id:'john-shop',client:'John B.',barber:null,kind:'general',messages:[]}];
state.threadId=state.threadId||'john-alex';
const originalExtraView=renderExtraView;
renderExtraView=function(v){if(v==='hFeedback')return ownerFeedback();if(v==='cFeedbackThanks')return feedbackThanks();if(v==='pMessages'||v==='messages'||v==='hMessages')return conversationInbox();return originalExtraView(v);};
function navItems(){return state.role==='Customer'?[['home','home','Home'],['book','calendar','Book'],['bookings','users','My visits'],['messages','message','Messages'],['more','settings','Account']]:state.role==='Barber Pro'?[['home','calendar','Today'],['pCalendar','calendar','Calendar'],['pTickets','scissors','Tickets'],['pMessages','message','Messages'],['more','settings','Account']]:[['home','home','Overview'],['calendar','calendar','Calendar'],['team','users','Team'],['hMessages','message','Inbox'],['more','settings','Manage']];}
function directory(){const groups=state.role==='Customer'?{'Your account':[['cProfile','Profile'],['cPayments','Payment preferences'],['cNotifications','Notifications'],['cHelp','Help & support']]}:state.role==='Barber Pro'?{'Your work':[['pProfile','Barber profile'],['pServices','Your services'],['availability','Availability'],['pPayout','Payouts']]}:{'Shop':[['settings','Shop settings'],['hServices','Services & pricing'],['hLoyalty','Loyalty program']],'Business':[['hCustomers','Customers'],['hPayouts','Transactions & payouts'],['reports','Reports'],['hFeedback','Private client feedback']]};return `${head(state.role==='Owner HQ'?'Manage your shop.':'Your account.','')}<div class="settings-groups">${Object.entries(groups).map(([title,links])=>`<section><h2>${title}</h2><div class="directory-links">${links.map(([page,label])=>`<button type="button" data-x="goto" data-page="${page}" data-r="${state.role}"><span class="row">${icon(({cProfile:'users',cPayments:'wallet',cNotifications:'bell',cHelp:'message',pProfile:'users',pServices:'scissors',availability:'calendar',pPayout:'wallet',settings:'settings',hServices:'scissors',hLoyalty:'gift',hCustomers:'users',hPayouts:'wallet',reports:'chart',hFeedback:'message'})[page]||'settings')}${label}</span>${icon('chevron')}</button>`).join('')}</div></section>`).join('')}</div>`;}
function reviewPage(){const visits=bookings.filter(b=>b.client==='John B.'&&b.ticket?.status==='approved').sort((a,b)=>b.ticket.approval.at-a.ticket.approval.at);return `<div class="narrow">${head('How was your visit?','Private feedback for the shop owner.')}<p class="muted">Your feedback is not posted on barber profiles or shown to your barber.</p>${visits.length?`<form id="client-review" class="panel" style="margin-top:24px"><label class="field">Completed visit<select name="visit">${visits.map(b=>`<option value="${b.id}" ${b.id===state.visitId?'selected':''}>${pretty(b.date)} · ${barbers.find(x=>x.id===b.barber).name} · ${shops[b.location||'scottsdale'].name}</option>`).join('')}</select></label><label class="field">Your rating<select name="stars" required><option value="">Choose a rating</option>${[5,4,3,2,1].map(n=>`<option value="${n}">${n} star${n===1?'':'s'}</option>`).join('')}</select></label><label class="field">Your feedback<textarea name="review" rows="4" minlength="3" maxlength="1000" required placeholder="Tell the owner about your experience."></textarea></label><button class="btn" type="submit">Send private feedback</button></form>`:`<div class="empty"><h2>Feedback follows your visit.</h2><p>Finish your visit and approve the final ticket first.</p>${linkPage('My visits','bookings','Customer')}</div>`}</div>`;}
function feedbackThanks(){const review=extras.reviews.find(r=>r.visit===state.feedbackVisit);return `<div class="success"><div class="success-mark">${icon('check')}</div>${head('Thanks for letting us know.','Your feedback is visible to the shop owner only.')}${review?.stars===5?`<section class="panel"><h2>Would you share your experience on Google?</h2><p class="muted" style="margin:16px 0">A public review helps others find ${shops[review.location||'scottsdale'].name}.</p><a class="btn full" href="${shops[review.location||'scottsdale'].google}" target="_blank" rel="noopener noreferrer">Leave a Google review ${icon('arrow')}</a></section>`:''}${linkPage('Back to home','home','Customer','secondary full','style="margin-top:20px"')}</div>`;}
function ownerFeedback(){if(state.role!=='Owner HQ')return head('Private to the owner.','');const list=[...extras.reviews].sort((a,b)=>(b.at||0)-(a.at||0));return `${head('Hear the whole story.','Private client feedback · Owner access only')}<div class="feedback-list">${list.length?list.map(r=>{const b=bookings.find(b=>b.id===r.visit);return `<article class="panel"><div class="row between"><strong>${r.stars} / 5</strong><small>${shops[r.location||b?.location||'scottsdale'].name}</small></div><h3 style="margin-top:16px">${barbers.find(x=>x.id===(r.barber||b?.barber))?.name||'Barber'}</h3><p class="muted" style="font-size:12px;margin-top:6px">${esc(b?.client||'Client')} · ${b?pretty(b.date):'Completed visit'}</p><p style="margin-top:16px">${esc(r.review)}</p></article>`;}).join(''):`<div class="empty"><h2>No private feedback yet.</h2><p>Client ratings and comments appear here after completed visits.</p></div>`}</div>`;}
function threadFor(client='John B.',barber='alex',kind='barber'){let t=extras.conversations.find(t=>t.client===client&&t.barber===barber&&t.kind===kind);if(!t){t={id:'thread-'+Date.now(),client,barber,kind,messages:[]};extras.conversations.push(t);}return t;}
function conversationInbox(){const role=state.role;const allowed=extras.conversations.filter(t=>role==='Owner HQ'||(role==='Customer'?t.client==='John B.':t.kind==='barber'&&t.barber===activeBarberId()));const thread=allowed.find(t=>t.id===state.threadId)||allowed[0];if(thread)state.threadId=thread.id;const name=t=>t.kind==='general'?'General shop inbox':role==='Customer'?barbers.find(b=>b.id===t.barber)?.name||'Your barber':role==='Barber Pro'?t.client:t.client+' ↔ '+(barbers.find(b=>b.id===t.barber)?.short||'Barber');return `${head(role==='Owner HQ'?'Your shop’s conversations.':'Messages.',role==='Owner HQ'?'General inbox and client–barber conversations.':'Keep in touch before and after your visit.')}<div class="inbox-layout"><section class="inbox-threads">${role==='Customer'?'':role==='Barber Pro'?xbutton('New message','new-thread','secondary full'):''}${role==='Barber Pro'&&state.pickClient?`<div class="client-picker"><h3>Choose a client</h3>${clientRecords.map((c,i)=>`<button type="button" data-talk="new-client" data-index="${i}">${esc(c.name)}</button>`).join('')}</div>`:''}${allowed.map(t=>`<button type="button" class="${thread?.id===t.id?'selected':''}" data-talk="select" data-id="${t.id}"><strong>${esc(name(t))}</strong><p>${t.kind==='general'?'Questions for the shop':role==='Owner HQ'?'Client–barber conversation':'Direct conversation'}</p></button>`).join('')}</section><section class="panel"><h2>${thread?esc(name(thread)):'No conversations yet'}</h2>${thread?`<p class="conversation-privacy">${thread.kind==='barber'?'':'Messages here go to the shop owner.'}</p><div class="thread-history">${thread.messages.length?thread.messages.map(m=>`<div class="message-bubble ${m.role===role?'out':''}"><small class="message-author">${esc(m.name)}${m.role==='Owner HQ'?' · Shop owner':''}</small><div>${esc(m.body)}</div></div>`).join(''):'<p class="muted" style="margin:28px 0">Start the conversation.</p>'}</div><form id="thread-message-form" class="message-form" data-thread="${thread.id}"><input name="body" aria-label="Message" placeholder="Write a message…" maxlength="1000" required><button class="btn" type="submit" aria-label="Send message">${icon('send')}</button></form>${role==='Customer'?xbutton('Message shop','general-thread','secondary','style="margin-top:20px"'):''}`:''}</section></div>`;}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;const d=el.dataset;if(d.talk==='select'){state.threadId=d.id;render();}if(d.x==='new-thread'){state.pickClient=!state.pickClient;render();}if(d.talk==='new-client'&&state.role==='Barber Pro'){const t=threadFor(clientRecords[Number(d.index)].name,activeBarberId());state.threadId=t.id;state.pickClient=false;save();render();}if(d.x==='general-thread'){const t=threadFor('John B.',null,'general');state.threadId=t.id;save();go('messages');}if(d.x==='message-barber'){const t=threadFor('John B.',state.barber);state.threadId=t.id;save();go('messages');}if(d.x==='message-client'){const t=threadFor(clientRecords[state.clientIndex].name,activeBarberId());state.threadId=t.id;save();go('pMessages');}});
document.addEventListener('submit',e=>{if(e.target.id!=='thread-message-form')return;e.preventDefault();const f=e.target,t=extras.conversations.find(t=>t.id===f.dataset.thread),body=String(new FormData(f).get('body')||'').trim();if(!t||!body)return;const role=state.role;if(role==='Customer'&&t.client!=='John B.')return;if(role==='Barber Pro'&&(t.kind!=='barber'||t.barber!==activeBarberId()))return;t.messages.push({role,name:role==='Customer'?(extras.profile.name||'John B.'):role==='Barber Pro'?activeStaff().name:'Shop owner',body:body.slice(0,1000),at:Date.now(),readBy:[messageViewer()],delivered:true});save();render();document.querySelector('#thread-message-form input')?.focus();});
document.addEventListener('change',e=>{if(e.target.id!=='shop-location-switch')return;extras.location=e.target.value;save();render();});
// The full internal screen registry is retained for coverage tests; user menus are task-specific.
screenIndex.Customer.push(['cFeedbackThanks','Feedback confirmation']);screenIndex['Barber Pro'].push(['pMessages','Messages']);screenIndex['Owner HQ'].push(['hFeedback','Private feedback']);
render();
